}
void tearDown(void) {
  xshim_close_display(dpy);
  canvas_free(&cv);
}

/* The hack packs and unpacks ordinary RGB565 itself, but images hold
 * canvas-order (byte-swapped) pixels. Pure red is 0xF800. */
void test_a_blended_point_reaches_the_image_in_canvas_order(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  draw_point(st, 2, 3, rgb2point(16, 255, 0, 0), 1.0f);
  TEST_ASSERT_EQUAL_HEX64(px_swap(0xF800), XGetPixel(st->buf, 2, 3));
  TEST_ASSERT_EQUAL_HEX64(0, XGetPixel(st->buf, 3, 3));
  binaryhorizon_free(dpy, 1, st);
}

/* A 16-bit image copies to the canvas a row at a time. */
void test_the_image_is_sixteen_bits_a_pixel(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  TEST_ASSERT_EQUAL_INT(16, st->buf->bits_per_pixel);
  TEST_ASSERT_EQUAL_INT(64, st->buf->width);
  TEST_ASSERT_EQUAL_INT(64, st->buf->height);
  binaryhorizon_free(dpy, 1, st);
}

/* Every `duration` seconds the hack starts again and allocates a new pixel
 * buffer without freeing the old one: 868 KB each time on the device. */
void test_a_timed_restart_does_not_leak_the_pixel_buffer(void) {
  struct state *st = binaryhorizon_init(dpy, 1);
  st->duration = 30;
  binaryhorizon_draw(dpy, 1, st);
  const size_t before = __sanitizer_get_current_allocated_bytes();
  for (int i = 0; i < 20; i++) {
    st->start_time = 0;
    binaryhorizon_draw(dpy, 1, st);
  }
  const size_t after = __sanitizer_get_current_allocated_bytes();
  TEST_ASSERT_TRUE(after <= before + 512);
  binaryhorizon_free(dpy, 1, st);
}

