  (void)d, (void)x, (void)y, (void)plane_mask, (void)format;
  XImage *im = XCreateImage(dpy, NULL, 16, ZPixmap, 0, NULL, w, h, 32, 0);
  if (im) im->data = (char *)calloc(h, (size_t)im->bytes_per_line);
  return im;
}
