static unsigned long binaryhorizon_draw(Display *display, Window win,
                                        void *closure) {
  struct state *st = (struct state *)closure;
  if (st->duration && time((time_t *)0) > st->start_time + st->duration) {
    free(st->buffer);
    st->buffer = NULL;
  }
